self.KB_CONTENT["card:779646"]={"id":"card:779646","ty":"card","sourceId":"779646","title":"『委外工單開立』的作業目的為何？","ver":"GP4以上","topic":"製令","keywords":["製令","廠商","生產","產品"],"y":"explain","answer":"做為委外發包派工單，針對多產品發包給同一廠商，同時紀錄發料產品/回貨產品/批號…數量等資訊，系統會自動產生所對應之『製令工單』，作為後續生產追蹤及成本計算依據。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
