self.KB_CONTENT["card:778120"]={"id":"card:778120","ty":"card","sourceId":"778120","title":"『領料單自動產生作業』中的『選擇製令狀態 (TA011)』為何？","ver":"GP4以上","topic":"領料單","keywords":["領料單","製令","生產","狀態"],"y":"other","answer":"* 未生產：只能選擇Y/N，預設值'Y'。* 已發料：只能選擇Y/N，預設值'N'。* 生產中：只能選擇Y/N，預設值'N'。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
