self.KB_CONTENT["card:792137"]={"id":"card:792137","ty":"card","sourceId":"792137","title":"『價格計算器』中的『利潤比率 (TO018)』為何？","ver":"GP4以上","topic":"比率","keywords":["比率","價格"],"y":"other","answer":"* 輸入與顯示時為乘以100.0，存入時除以100。 例：50% 存入值為 0.5000。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
