self.KB_CONTENT["card:784426"]={"id":"card:784426","ty":"card","sourceId":"784426","title":"『資產出售建立作業』中的『總帳帳別 (TC102)』為何？","ver":"GP4以上","topic":"總帳帳別","keywords":["總帳帳別","資產","傳票","拋轉"],"y":"other","answer":"* 拋轉成會計傳票後由會計系統回寫。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
