self.KB_CONTENT["field:792692"]={"id":"field:792692","ty":"field","sourceId":"792692","title":"選擇排序","ver":"GP4以上","topic":"","keywords":[],"job":"受訂確認書","code":"","answer":"* 列印時報表之排序方式，分別為1.訂單單號+品號+預交日、2.訂單單號+序號+品號+預交日。","file":"fields.jsonl"};
